/**
 * Users: data-facet only. Not an org identity — no org.ts bag, never in an
 * org export — but app streams reference users (email-keyed data lookups,
 * e.g. field default assignees), so extraction must resolve them.
 */
import { NO_CANVAS, NO_CATALOG, NO_LIFECYCLE, } from "../../graph/types.js";
export const userModule = {
    kind: "user",
    stream: { role: "streamMember" },
    data: {
        participates: true,
        lookupAttr: "email",
        // A USER field's `default_value` (entities/field/types.ts's
        // OrgFieldRefValue) and an access policy's `user_ids` (board issue #69)
        // both round-trip as `data.elementum_user` lookups via the generic
        // `rawLookup` mechanism — real, tested coverage, so this participates in
        // the byte-fidelity roundtrip scope. A captured `elementum_user` data
        // block for any OTHER reason still fails loud (missing from build
        // output) rather than silently passing — surfacing gaps instead of
        // hiding them was the tradeoff of leaving this false; if that surfaces a
        // real one, extend the reproducing path rather than reverting this flag.
        referencedByBuild: true,
    },
    authoring: { unit: "none" },
    parents: [{ parent: "org", child: "user" }],
    resource: { shape: "single", resourceType: "elementum_user", adoptable: false },
    lifecycle: NO_LIFECYCLE,
    canvas: NO_CANVAS,
    catalog: NO_CATALOG,
};
